-- Paket ABT "abt-x3-tuntutan-sinkron-21okt" (21 Okt 2026): tuntutan akibat perceraian yang diminta petitum.
-- Pola pembaca petitum (nafkah iddah, mut'ah, nafkah madliyah) di 25 variabel paket u2 tidak lagi menyala atas nama pihak (Rosidah, Mutahir, ...);
-- variabel baru 3400 = keadaan dan kutipan tiap tuntutan untuk layar (tidak dicetak). 1 variabel baru, 25 baris diubah.
-- PULIH (deterministik): variabel baru dihapus HANYA bila isinya masih persis paket; baris yang diubah dikembalikan dari tabel sementara x3_lama
-- (dibuat pulih-satker.sh dari cadangan/abt_variabel-sebelum.sql) HANYA bila isinya masih isi BARU paket dan baris cadangan masih isi LAMA yang diharapkan.
-- Jalankan lewat pulih-satker.sh (bukan langsung): tabel x3_lama harus ada.
START TRANSACTION;
DELETE FROM abt_variabel WHERE (no_var=3400 AND MD5(nama)='e21f226243226e675293c095f12f0d7e' AND data_type='data_sql' AND IFNULL(data_tabel,'')='' AND IFNULL(data_kolom,'')='' AND IFNULL(urutan_data,0)=0 AND referensi IS NULL AND multi_sidang IS NULL AND locked=0 AND IFNULL(MD5(sql_query),'-')='1fb6b241b8eccf64c3444fa0ab044b2d' AND IFNULL(MD5(default_data),'-')='-');
